/** The general score (an appendix to the nine families: it reads them, it does not drive them). */
export const SCORE_FAMILY: EquationFamily = {
  id: 'score',
  title: { es: 'Anexo: puntaje general (3 niveles)', en: 'Appendix: general score (3 levels)' },
  summary: {
    es: `Anclado al inicio de cada nivel: el componente de carbono vale 100 en ${n(CARBON_CEILING_FACTOR - 1, 'es')}·c₀ y 0 en ${n(CARBON_CEILING_FACTOR, 'es')}·c₀; el de PBI se llena al ${GDP_FULL_MULTIPLE}× del PBI inicial. Cada ruta multiplica el puntaje final del nivel.`,
    en: `Anchored to each level's start: the carbon component is 100 at ${CARBON_CEILING_FACTOR - 1}·c₀ and 0 at ${CARBON_CEILING_FACTOR}·c₀; the GDP one fills up at ${GDP_FULL_MULTIPLE}× the starting GDP. Each route multiplies the level's final score.`,
  },
  formula: both(`C_sc = 100·clip((${CARBON_CEILING_FACTOR}·c₀ − c)/c₀, 0, 1);  P_sc = 100 − π̄;  X = (F + E + W + St)/4;  Y_sc = min(100, 100·Y/(${GDP_FULL_MULTIPLE}·Y₀))
S1 = 10·(${SCORE_WEIGHTS[1].biodiversity}·B + ${SCORE_WEIGHTS[1].carbon}·C_sc + ${SCORE_WEIGHTS[1].economic}·E)
S2 = 10·(${SCORE_WEIGHTS[2].biodiversity}·B + ${SCORE_WEIGHTS[2].carbon}·C_sc + ${SCORE_WEIGHTS[2].pressure}·P_sc + ${SCORE_WEIGHTS[2].externalities}·X)
S3 = 10·(${SCORE_WEIGHTS[3].biodiversity}·B + ${SCORE_WEIGHTS[3].carbon}·C_sc + ${SCORE_WEIGHTS[3].pressure}·P_sc + ${SCORE_WEIGHTS[3].externalities}·X + ${SCORE_WEIGHTS[3].gdp}·Y_sc)`),
};
